	// The PAT is write-only: it is encrypted before storage and never returned.
	SetWorkspaceRepoBindingCredential(context.Context, *connect.Request[v1.SetWorkspaceRepoBindingCredentialRequest]) (*connect.Response[v1.SetWorkspaceRepoBindingCredentialResponse], error)
	// ValidateWorkspaceRepoBinding probes the repository with the stored
	// credential (visibility/read, branch existence, write capability, PR/MR
	// capability as required by the write mode), persists the outcome on the
	// binding, and returns it.
	ValidateWorkspaceRepoBinding(context.Context, *connect.Request[v1.ValidateWorkspaceRepoBindingRequest]) (*connect.Response[v1.ValidateWorkspaceRepoBindingResponse], error)
